use openwebide_core::{editor::{Document, Selection, SyntaxPreparations}, highlight::Language};
use std::{sync::Arc, time::{Instant, Duration}};
fn main() {
    for repeat in [1usize, 256, 2048, 8192, 32768] {
        for kind in ["html-code", "html-comment", "html-bodies", "markdown-code"] {
            let (language, source) = match kind {
                "html-code" => (Language::Html, format!("<script>\n{}\n</script>", "function run() {}\n".repeat(repeat))),
                "html-comment" => (Language::Html, format!("<script>/*{}*/ function run() {{}}\n</script>", "opaque text and words\n".repeat(repeat))),
                "html-bodies" => (Language::Html, "<script>function run() {}</script>\n".repeat(repeat)),
                _ => (Language::Markdown, format!("```javascript\n{}\n```", "function run() {}\n".repeat(repeat))),
            };
            let source = Arc::new(source);
            let mut document = Document::new(source.as_str());
            document.set_selections(vec![Selection::caret(source.find("{}").unwrap() + 1)]).unwrap();
            let mut cache = SyntaxPreparations::<u8>::default();
            let started = Instant::now();
            let deadline = started + Duration::from_millis(12);
            let (status, prepared) = cache.prepare_shared(1, language, source.clone(), 4, || Instant::now() <= deadline);
            let preparation = started.elapsed().as_secs_f64() * 1000.0;
            let structure = prepared.as_ref().and_then(|analysis| analysis.structure());
            let started = Instant::now();
            if let Some(structure) = structure {
                document.type_character_with_context('(', structure).unwrap();
            } else {
                document.type_character('(', language).unwrap();
            }
            let edit = started.elapsed().as_secs_f64() * 1000.0;
            println!(r#"{{"kind":"{}","bytes":{},"repeat":{},"status":"{:?}","context":{},"preparationMs":{},"editMs":{}}}"#,kind,source.len(),repeat,status,structure.is_some(),preparation,edit);
        }
    }
}
